export function needsLightPad(entry: {
  id: string;
  source?: string;
  category?: string;
}): boolean {
  const pack =
    entry.source === "crypto" || entry.category === "crypto"
      ? "crypto"
      : entry.source === "dev" || entry.category === "dev"
        ? "dev"
        : null;
  if (!pack) return false;
  return DARK_ON_DARK_KEYS.has(`${pack}/${entry.id}`);
}
